/**
 * Plain-language definitions keyed by lesson title.
 *
 * These replace the generated placeholder sentence ("X is a practical part of
 * Y") that previously opened almost every lesson. Each entry is written to be
 * understood on first read by someone new to the topic, and to stay accurate
 * enough for someone revising before an interview.
 *
 * Titles repeat across courses on purpose — one definition serves every course
 * that teaches the topic.
 */
export const topicDefinitions: Record<string, string> = {
  // ---------------------------------------------------------------- analytics
  "Why Data Analytics Matters": "Analytics matters because decisions made on evidence are cheaper to correct than decisions made on assumption. It replaces opinion with a measurable, repeatable answer.",
  "Real-World Applications": "The same analytics workflow appears everywhere: retailers forecast demand, banks score risk, hospitals plan capacity, and product teams measure whether a change helped.",
  "Descriptive Analytics": "Descriptive analytics summarises what already happened, such as last month's revenue by region. It reports facts rather than explaining or predicting them.",
  "Diagnostic Analytics": "Diagnostic analytics investigates why a result occurred by comparing segments, periods, and possible drivers until the explanation is supported by evidence.",
  "Predictive Analytics": "Predictive analytics uses historical patterns to estimate what is likely to happen next, always with a stated level of uncertainty.",
  "Prescriptive Analytics": "Prescriptive analytics goes one step past a forecast and recommends which action to take, given the goal and the constraints.",
  "Data-Driven Decision Making": "Data-driven decision making means naming the decision first, gathering evidence that could change it, and recording what the evidence actually supported.",
  "From Data to Insight": "An insight is not a number. It is a finding that is specific, surprising enough to matter, supported by checked data, and connected to an action someone can take.",
  "Finding the Important Insight": "The important insight is the one that would change a decision. Test each candidate finding by asking what someone would do differently if they believed it.",
  "Business Questions": "A good business question names the decision, the measure, the population, and the time window, so the analysis has one defensible answer.",
  "Communicating Results": "Communicating results means leading with the answer, showing the evidence that supports it, and stating the assumptions and limits honestly.",
  "Presenting Data to Non-Technical People": "Lead with the decision and the recommendation, use one chart per message, define every term once, and keep the method available but out of the main path.",
  "Common Analyst Mistakes": "The frequent failures are analysing before the question is clear, trusting uninspected data, confusing correlation with cause, and presenting a chart without a recommendation.",

  "Quantitative Data": "Quantitative data is recorded as numbers you can meaningfully do arithmetic on, such as price, weight, or duration.",
  "Qualitative Data": "Qualitative data describes qualities or categories rather than amounts, such as a colour, a product category, or a free-text review.",
  "Numerical Data": "Numerical data is measured on a scale. Discrete values are counted in whole units; continuous values can take any value in a range.",
  "Categorical Data": "Categorical data places each record in a group. Nominal categories have no order; ordinal categories do, such as small, medium, and large.",
  "Primary Data": "Primary data is collected first-hand for the current question, so you control its definitions, quality, and coverage.",
  "Secondary Data": "Secondary data was collected by someone else for another purpose, so it is faster to obtain but must be checked for fit, freshness, and bias.",
  CSV: "A CSV file stores tabular data as plain text with one record per line and a delimiter between fields. It is universal, but it carries no data types and no formatting.",
  JSON: "JSON stores data as nested key–value pairs and arrays. It suits APIs and event logs, and usually needs flattening before tabular analysis.",
  XML: "XML stores data in nested, self-describing tags. It is verbose compared with JSON but still common in enterprise and document systems.",
  "Internal vs External Data": "Internal data comes from your own systems and is well understood but limited in scope. External data adds market context but needs validation before you rely on it.",
  Databases: "A database stores data in an organised, queryable structure with rules that keep it valid, so many people and applications can read and write it safely.",
  Tables: "A table stores one kind of record. Each row is one instance, each column is one attribute, and a key identifies each row uniquely.",

  "Rows and Columns": "In a spreadsheet a row is a single record and a column is a single field. Keeping one record per row and one meaning per column is what makes later analysis possible.",
  Sorting: "Sorting reorders rows by one or more columns so that ranking, extremes, and duplicates become visible.",
  Filtering: "Filtering hides rows that do not meet a condition so you can work with the subset that answers the question, without deleting anything.",
  "Basic Formulas": "A formula computes a value from other cells. Because it recalculates automatically, the workbook stays correct when the underlying data changes.",
  IF: "IF returns one value when a condition is true and another when it is false, which lets a sheet apply a business rule row by row.",
  SUMIF: "SUMIF adds only the values whose matching rows satisfy a condition, giving a conditional total without a pivot table.",
  COUNTIF: "COUNTIF counts the rows that satisfy a condition, which is the quickest way to size a segment or check a data-quality rule.",
  XLOOKUP: "XLOOKUP searches a range for a value and returns the matching entry from another range. It replaces VLOOKUP and can search in either direction.",
  "INDEX + MATCH": "MATCH finds the position of a value in a range and INDEX returns whatever sits at that position, so the pair can look up a value in any direction.",
  "Pivot Tables": "A pivot table summarises many rows into a compact table by grouping on chosen fields and aggregating a measure, without altering the source data.",
  "Pivot Charts": "A pivot chart draws a pivot table, so the visual updates whenever the pivot's fields, filters, or source data change.",
  "Conditional Formatting": "Conditional formatting changes a cell's appearance based on its value, making exceptions and thresholds visible without reading every number.",
  "Data Cleaning in Excel": "Cleaning in Excel means fixing types, trimming stray spaces, splitting merged fields, removing duplicates, and standardising categories before any analysis begins.",
  "Power Query": "Power Query records each transformation as a repeatable step, so refreshing the source re-applies the whole cleaning process automatically.",
  "Excel Dashboard": "An Excel dashboard combines a clean data sheet, pivot summaries, and charts with slicers so a reader can answer a small set of related questions in one view.",
  "Excel for Analytics": "Excel is a practical analytics tool for datasets that fit comfortably in memory: it handles cleaning, lookups, aggregation, and presentation in one place.",

  SELECT: "SELECT chooses which columns to return. The database evaluates FROM, WHERE, GROUP BY, and HAVING first, then SELECT, then ORDER BY.",
  WHERE: "WHERE keeps only the rows that satisfy a condition. It runs before grouping, so it cannot reference an aggregate.",
  "ORDER BY": "ORDER BY sorts the final result. It is the last clause to run, so it can use column aliases defined in SELECT.",
  "GROUP BY": "GROUP BY collapses rows that share a value into one row per group, so aggregate functions can summarise each group.",
  HAVING: "HAVING filters groups after aggregation, which is what WHERE cannot do. Use WHERE for rows and HAVING for aggregates.",
  "Aggregate Functions": "Aggregate functions turn many rows into one value: COUNT, SUM, AVG, MIN, and MAX. Most of them ignore NULL, which is a common source of surprise.",
  COUNT: "COUNT(*) counts rows; COUNT(column) counts non-NULL values in that column. The difference is often the first sign of a data-quality issue.",
  SUM: "SUM adds the numeric values in a column, skipping NULL. It is only meaningful when every row uses the same unit.",
  AVG: "AVG returns the mean of the non-NULL values. Because it ignores NULL rather than treating it as zero, the denominator may not be what you expect.",
  MIN: "MIN returns the smallest value in a column and quickly exposes impossible values such as negative prices.",
  MAX: "MAX returns the largest value in a column and is often the fastest way to find a stale or runaway record.",
  "INNER JOIN": "An INNER JOIN returns only the rows whose join key exists in both tables. Rows without a match disappear, which can silently shrink a result.",
  "LEFT JOIN": "A LEFT JOIN keeps every row from the left table and fills the right-hand columns with NULL where no match exists, which makes it the right tool for finding gaps.",
  "RIGHT JOIN": "A RIGHT JOIN keeps every row from the right table. It is a mirror of LEFT JOIN and is usually rewritten as one for readability.",
  JOINs: "A join combines rows from two tables on a matching key. The join type decides what happens to rows that have no match.",
  Subqueries: "A subquery is a query nested inside another. The inner query runs first and its result is used by the outer query as a value, a list, or a table.",
  CTEs: "A common table expression names an intermediate result with WITH, so a long query can be read as a sequence of clear steps instead of nested brackets.",
  "Window Functions": "A window function computes a value across a set of related rows while keeping every row, which is how running totals, rankings, and period-over-period changes are written.",
  CASE: "CASE applies if-then logic inside a query, letting you derive a category, bucket a number, or handle an exception without leaving SQL.",
  "SQL Data Cleaning": "Cleaning in SQL means standardising text, casting types, replacing invalid values, de-duplicating with window functions, and recording each rule so it is repeatable.",
  "Relational Databases": "A relational database stores data in tables linked by keys, and enforces rules so related records stay consistent as the data changes.",
  "SQL Basics": "SQL is declarative: you describe the result you want and the database decides how to produce it. Learning the clause order is what makes queries predictable.",
  "Advanced SQL": "Advanced SQL combines window functions, CTEs, conditional aggregation, and set operations to answer questions that would otherwise need application code.",
  "Why QA Needs SQL": "A tester uses SQL to confirm that what the interface displays matches what the database actually stored, which is where many defects hide.",
  "Database Testing": "Database testing verifies that data is stored, updated, and removed correctly, that constraints hold, and that the UI and the stored records agree.",

  "Why Python?": "Python is the common language of analytics because its data libraries are mature, its syntax is readable, and the same script can clean, analyse, model, and report.",
  "Python Setup": "A working setup means a known Python version, an isolated virtual environment, and a pinned list of packages, so the analysis runs the same way tomorrow.",
  Variables: "A variable is a name bound to a value. Descriptive names are the cheapest documentation a script can have.",
  "Data Types": "A data type decides what values are allowed and which operations make sense. Most data bugs trace back to a value stored as the wrong type.",
  "Python Data Types": "Python's core types are numbers, strings, booleans, and the containers list, tuple, set, and dictionary. Choosing the right container simplifies the code that follows.",
  Lists: "A list is an ordered, changeable sequence. It is the default choice when order matters and items may be added or removed.",
  Tuples: "A tuple is an ordered sequence that cannot be changed after creation, which makes it safe to use as a fixed record or a dictionary key.",
  Sets: "A set stores unique, unordered values and answers membership and de-duplication questions far faster than a list.",
  Dictionaries: "A dictionary maps keys to values for fast lookup by name. It is the natural shape for a record with labelled fields.",
  Loops: "A loop repeats work across a sequence. In data work, prefer a vectorised library operation over a loop whenever one exists.",
  Functions: "A function names a reusable piece of logic with clear inputs and one output, which makes an analysis easier to test and to trust.",
  Operators: "Operators combine values: arithmetic computes, comparison returns booleans, and logical operators join conditions.",
  Conditions: "A condition selects which branch of code runs. Handling the unexpected branch explicitly is what separates a script from a reliable one.",
  "File Handling": "File handling reads and writes data on disk. Opening files with a context manager guarantees they are closed even when an error occurs.",
  "Exception Handling": "Exception handling catches predictable failures so a script reports a useful message instead of stopping at a stack trace.",
  "Error Handling": "Error handling decides what happens when something fails: retry, fall back, or report clearly. Silent failure is the outcome to avoid.",
  NumPy: "NumPy provides fast numeric arrays and vectorised maths, which is why almost every Python data library is built on top of it.",
  "NumPy Introduction": "NumPy stores numbers in a compact, typed array so whole-array arithmetic runs in optimised code rather than a Python loop.",
  "NumPy Arrays": "A NumPy array holds values of one type in a fixed shape, which makes memory use predictable and operations fast.",
  "Array Operations": "Array operations apply to every element at once. Broadcasting lets arrays of different shapes combine without writing loops.",
  Pandas: "pandas adds labelled tables to Python, so rows and columns can be filtered, grouped, joined, and reshaped with readable code.",
  "Pandas Introduction": "pandas provides the Series (one labelled column) and the DataFrame (a labelled table), which together cover most tabular work.",
  Series: "A Series is a one-dimensional labelled array. Its index is what makes alignment between columns automatic.",
  DataFrames: "A DataFrame is a table of Series that share an index. Almost every pandas operation returns a new DataFrame rather than editing in place.",
  "Loading CSV": "Reading a CSV means more than opening it: check the delimiter, the encoding, the header row, the inferred types, and the row count against the source.",
  "Loading Excel": "Reading an Excel file requires naming the sheet and the header row, and re-checking types, since spreadsheets often mix numbers and text in one column.",
  "Loading JSON": "Loading JSON usually needs a flattening step, because nested objects and arrays must become columns before tabular analysis works.",
  "Reading CSV Files": "Loading a CSV is the first checkpoint of an analysis: confirm the shape, the column types, and a few known rows before doing anything else.",
  "Filtering Data": "Filtering selects the rows that match a condition. Keeping the filter explicit and named makes the analysis reproducible.",
  "Sorting Data": "Sorting orders rows by chosen columns, which is how ranking questions and top-N summaries are answered.",
  GroupBy: "GroupBy splits rows into groups, applies an aggregation to each, and combines the results into one summary table.",
  Aggregation: "Aggregation reduces many rows to one summary value per group, such as a count, a total, or an average.",
  "Merging DataFrames": "Merging joins two tables on a key. Always check the row count afterwards: an unexpected increase means the key was not unique.",
  "Data Selection": "Selection chooses the rows and columns to work with. Using explicit label-based selection avoids the ambiguity that causes silent errors.",

  "Why Data Quality Matters": "Every downstream number inherits the quality of its input. An error found during cleaning costs minutes; the same error found in a board report costs credibility.",
  "Missing Values": "A missing value means no data was recorded. The right treatment depends on why it is missing, so investigate the cause before choosing to fill or drop it.",
  "Duplicate Records": "A duplicate is the same real-world entity recorded more than once. Duplicates inflate totals, so define what makes a record unique before removing any.",
  "Duplicate Values": "Duplicate values repeat within a column. Some are legitimate; the ones that matter are those that break an assumed uniqueness rule.",
  "Duplicate Data": "Duplicated rows quietly bias both reports and models, because the repeated pattern is counted more than once.",
  "Incorrect Values": "Incorrect values are stored but impossible or inconsistent, such as a negative age or a delivery date before the order date. Range and rule checks find them.",
  "String Cleaning": "String cleaning trims whitespace, standardises case, fixes encoding, and unifies spellings so that categories group correctly.",
  "Date Cleaning": "Date cleaning parses text into real dates, fixes ambiguous day/month order, and standardises time zones, so sorting and period comparisons are correct.",
  Outliers: "An outlier is a value far from the rest of the data. It may be a recording error or the most important observation in the dataset, so investigate before removing.",
  "Handling Outliers": "Decide by cause: correct genuine errors, keep real extremes and use robust methods, and document whatever you chose to do.",
  "Outlier Detection": "Outlier detection flags unusual values using distance from the mean, the interquartile range, or a model of what is normal.",
  "Data Transformation": "Transformation reshapes data into the form the analysis needs: deriving fields, pivoting, changing units, or aggregating to another grain.",
  Normalization: "Normalisation rescales values into a fixed range, usually zero to one, so features measured on different scales can be compared or combined.",
  Standardization: "Standardisation centres a feature on zero and scales it by its standard deviation, so values are expressed in standard deviations from the mean.",
  Scaling: "Scaling puts features on a comparable range. Fit the scaler on training data only, then apply it to new data, or you leak information.",
  Encoding: "Encoding converts categories into numbers a model can use. One-hot encoding suits unordered categories; ordinal encoding suits genuinely ranked ones.",
  "Encoding Categorical Data": "Categorical encoding turns labels into numeric features. Applying an ordinal code to unordered categories invents a ranking that does not exist.",
  "Data Validation": "Validation checks data against explicit rules — types, ranges, uniqueness, and relationships — and fails loudly when a rule is broken.",
  "Data Quality Checks": "Quality checks are automated assertions run on every refresh: row counts, null rates, allowed values, and totals compared against a trusted source.",
  "Feature Selection": "Feature selection keeps the inputs that carry signal and drops the rest, which reduces overfitting, training time, and maintenance cost.",
  "Feature Engineering": "Feature engineering creates inputs that express what actually matters, such as a ratio, a time-since-event, or an aggregate, and is often worth more than a better algorithm.",
  "Train/Test Split": "Splitting reserves a portion of the data that the model never sees during training, so the final score reflects new-data performance.",
  "Data Sources": "A data source is where records originate: an application database, a file export, an API, or a third-party feed. Each has its own freshness and reliability profile.",
  "Web Data": "Web data is collected from APIs or pages. Respect the terms of use and rate limits, and expect the structure to change without warning.",

  "Why EDA?": "Exploration protects you from analysing the wrong thing. It reveals the shape, gaps, and surprises of a dataset before any conclusion depends on them.",
  "Asking Questions": "Good exploration is question-led: what should this look like, what would surprise me, and what would prove me wrong.",
  Mode: "The mode is the most frequent value. It is the only summary of centre that works for unordered categories.",
  Percentiles: "A percentile is the value below which a given share of observations falls. The median is the 50th percentile.",
  Covariance: "Covariance measures whether two variables move together, but its size depends on the units, which is why correlation is usually reported instead.",
  "Detecting Patterns": "Pattern detection looks for trends, cycles, clusters, and relationships that repeat, then asks whether a mechanism could explain them.",
  "Detecting Anomalies": "Anomaly detection finds observations that break the established pattern, which may signal fraud, a fault, or a broken data pipeline.",
  "Univariate Analysis": "Univariate analysis examines one variable at a time: its distribution, centre, spread, and unusual values.",
  "Bivariate Analysis": "Bivariate analysis examines the relationship between two variables, using a scatter plot, a cross-tab, or a correlation.",
  "Multivariate Analysis": "Multivariate analysis studies several variables together, which can reveal that an apparent two-variable relationship is driven by a third.",
  "Distribution Analysis": "Distribution analysis describes how values are spread — the shape, the centre, the tails — which determines which summaries and tests are valid.",
  "Automated EDA": "Automated profiling tools produce a fast first pass over a dataset, but the judgement about what matters still belongs to the analyst.",

  "Bar Charts": "A bar chart compares a measure across categories using bar length from a zero baseline, which is the encoding people read most accurately.",
  "Line Charts": "A line chart shows how a measure changes over ordered time. The connecting line implies continuity, so only use it when that is true.",
  "Pie Charts": "A pie chart shows parts of one whole. It works for a few clearly different slices and fails for close comparisons.",
  Histograms: "A histogram bins one numeric variable and plots the counts, revealing the shape, spread, and gaps of a distribution.",
  "Scatter Plots": "A scatter plot places each observation by two numeric values, which is the fastest way to see a relationship, a cluster, or an outlier.",
  "Box Plots": "A box plot summarises a distribution by its quartiles and whiskers, which makes comparing several groups at once straightforward.",
  Heatmaps: "A heatmap encodes matrix values as colour, so patterns across many rows and columns become visible at once.",
  "Correlation Heatmap": "A correlation heatmap shows every pairwise linear relationship in one grid, which is a fast way to spot redundant features.",
  Matplotlib: "matplotlib is the foundational Python plotting library. It is verbose but gives complete control over every element of a figure.",
  Seaborn: "seaborn builds on matplotlib with statistical chart types and sensible defaults, so common exploratory plots take one line.",
  Plotly: "Plotly produces interactive charts with hover, zoom, and selection, which suits exploration and dashboards more than print.",
  "Interactive Visualization": "Interactivity lets a reader ask follow-up questions themselves, but every interaction must still lead to an honest reading of the data.",
  "Common Visualization Mistakes": "The recurring errors are truncated axes, pie charts with too many slices, colour as the only cue, missing units, and charts with no stated message.",

  "What is a Dashboard?": "A dashboard is a focused view of related measures built for one audience and one recurring decision, not a collection of every available chart.",
  "Dashboard vs Report": "A dashboard is monitored continuously and answers 'what is happening now'. A report is produced periodically and explains a period in depth.",
  "Importing Data": "Importing connects a tool to a source and defines how often it refreshes. Getting the grain and the types right here prevents rework later.",
  Relationships: "Relationships link tables on shared keys so a measure defined once can be sliced by any connected dimension.",
  "DAX Introduction": "DAX is the formula language of Power BI. Its measures are evaluated in the filter context of the visual they appear in, which is the concept to master first.",
  KPIs: "A key performance indicator is a measure tied to an objective, with a defined calculation, an owner, and a target. Without a target it is only a metric.",
  Charts: "A chart encodes data as position, length, angle, or colour. Choosing the encoding that the eye reads most accurately is most of the design work.",
  Filters: "A filter narrows the data behind a visual. Always show which filters are applied, or a reader will misread the number.",
  Slicers: "A slicer is a visible on-page filter control that lets a reader change the view without editing the report.",
  "Dashboard Design": "Good dashboard design starts from the decision: a headline measure top-left, related detail grouped nearby, clear labels, and no chart that no one acts on.",
  "Dashboard Best Practices": "Keep to one audience, lead with the most important number, use consistent colour meaning, label units, and remove anything that has never changed a decision.",
  "Tableau Introduction": "Tableau connects to a source and builds visuals by dragging fields to shelves, then combines worksheets into interactive dashboards.",

  // ---------------------------------------------------------------- science
  "Why Data Science?": "Data science exists to turn uncertain, messy evidence into decisions and products that measurably work, and to say honestly how confident we can be.",
  "Role of a Data Scientist": "A data scientist frames the problem, prepares the data, models it, quantifies the uncertainty, and communicates a result that a business can act on.",
  "Data Science Lifecycle": "The lifecycle runs from business understanding through data collection, preparation, exploration, modelling, evaluation, deployment, and monitoring — and it loops.",
  "Why Statistics?": "Statistics is how we tell a real effect from a coincidence, and how we attach an honest level of confidence to a conclusion drawn from a sample.",
  "Population vs Sample": "The population is everyone we want to describe; the sample is who we actually measured. Every inference depends on the sample representing the population.",
  Probability: "Probability quantifies how likely an outcome is on a scale from zero to one, which gives us a language for uncertainty.",
  "Conditional Probability": "Conditional probability is the chance of an event given that another has already occurred. Ignoring the condition is a common source of wrong conclusions.",
  "Bayes Theorem": "Bayes' theorem updates a prior belief with new evidence to produce a posterior belief, which is the formal version of changing your mind proportionally.",
  "Probability Distributions": "A distribution describes how likely each value is. Recognising the distribution tells you which summaries and tests are appropriate.",
  "Normal Distribution": "The normal distribution is a symmetric bell shape where about 68%, 95%, and 99.7% of values fall within one, two, and three standard deviations of the mean.",
  "Hypothesis Testing": "Hypothesis testing asks whether the observed effect is larger than what random variation alone would plausibly produce, under stated assumptions.",
  "A/B Testing": "An A/B test randomly assigns users to two variants and compares one pre-declared metric, so the difference can be attributed to the change rather than to chance.",
  "Model Serialization": "Serialisation saves a trained model to a file so it can be loaded and used later without retraining. Record the library versions alongside it.",
  Deployment: "Deployment makes a model or application available to real users with the reliability, security, and monitoring that real use requires.",
  "Model Monitoring": "Monitoring watches live inputs, predictions, and outcomes so quality decline is detected by a system rather than by a customer complaint.",
  "MLOps Introduction": "MLOps applies engineering discipline to machine learning: versioned data, reproducible training, automated deployment, and continuous monitoring.",
  "Time Series Basics": "Time series data is ordered by time, so observations are related to their neighbours. That order must be respected when splitting and validating.",
  Forecasting: "Forecasting projects a time series forward from trend, seasonality, and known events, and reports a range rather than a single number.",
  "Anomaly Detection": "Anomaly detection learns what normal looks like and flags observations that depart from it far enough to warrant investigation.",
  "Recommendation Systems": "A recommender predicts what a user is likely to want, from their own history, from similar users, or from item attributes.",
  "NLP Introduction": "Natural language processing turns text into a structured representation a model can use, then applies models to classify, extract, or generate language.",
  "Text Data": "Text is unstructured, so it must be normalised, tokenised, and represented numerically before most models can use it.",
  "Sentiment Analysis": "Sentiment analysis classifies the attitude expressed in text. Sarcasm, negation, and domain language are where naive approaches fail.",
  "Dimensionality Reduction": "Dimensionality reduction compresses many correlated features into fewer, so models train faster and are less prone to overfitting.",
  PCA: "Principal component analysis finds the directions that capture the most variance in the data and re-expresses the observations along those directions.",
  "Data Science Portfolio": "A portfolio proves capability with a few complete projects: a real problem, a documented method, an honest evaluation, and a clear write-up.",
  "Data Science Interview Preparation": "Interviews test whether you can frame a problem, justify a method, explain a trade-off, and admit the limits of your result.",

  // ---------------------------------------------------------------- ML
  "AI vs ML vs Deep Learning": "AI is the broad goal of machine intelligence, machine learning is the subset that learns from data, and deep learning is the subset of ML that uses many-layered neural networks.",
  "Why Machine Learning?": "Machine learning is worth using when the rules are too numerous or too subtle to write by hand, but examples of the right answer are available.",
  "How Machines Learn": "A model starts with a guess, measures how wrong it is on examples, adjusts its parameters to reduce that error, and repeats until improvement stops.",
  "Traditional Programming vs ML": "Traditional programming turns rules and data into answers. Machine learning turns data and answers into rules.",
  "Machine Learning Workflow": "The workflow runs from framing the problem through data preparation, training, evaluation, tuning, deployment, and monitoring — and returns to the start when the data shifts.",
  "Semi-Supervised Learning": "Semi-supervised learning uses a small labelled set together with a large unlabelled set, which suits domains where labelling is expensive.",
  "Self-Supervised Learning": "Self-supervised learning creates its own training signal from the structure of the data itself, such as predicting a hidden part of an input.",
  "Understanding Datasets": "Before modelling, know what one row represents, what each column means, how the data was collected, and what is missing or biased.",
  "Features and Labels": "Features are the inputs a model learns from; the label is the answer it is trying to predict. Any feature unavailable at prediction time causes leakage.",
  "Training Data": "Training data is the portion used to fit the model's parameters. It should look like the data the model will meet in production.",
  "Validation Data": "Validation data guides choices such as hyperparameters and model selection. Because you tune against it, it is no longer an unbiased estimate.",
  "Test Data": "Test data is held back and used once, at the end, to estimate real-world performance honestly.",
  "Feature Scaling": "Scaling brings features onto a comparable range, which matters for distance-based and gradient-based algorithms and not at all for trees.",
  "What is Regression?": "Regression predicts a continuous number, such as a price or a duration, and is judged by how far its predictions sit from the truth.",
  "Linear Regression Intuition": "Linear regression fits the straight line that minimises the squared distance between predictions and actual values.",
  "Simple Linear Regression": "Simple linear regression uses one input to predict a number, learning a slope and an intercept from the training data.",
  "Multiple Linear Regression": "Multiple linear regression uses several inputs at once, learning a coefficient for each that holds the others constant.",
  "Cost Function": "A cost function scores how wrong the model currently is, giving training a single number to minimise.",
  "Learning Rate": "The learning rate sets the step size during training. Too large and it overshoots; too small and it barely moves.",
  "Training a Regression Model": "Training fits parameters on the training split, then reports error on held-out data — never on the data used to fit it.",
  "Evaluating Regression": "Regression is evaluated by error magnitude: MAE for average error in real units, RMSE when large errors matter more, and R² for variance explained.",
  "What is Classification?": "Classification assigns an input to one of a fixed set of categories and is judged by which kinds of mistakes it makes, not only how many.",
  "Binary Classification": "Binary classification chooses between two outcomes. The decision threshold, not just the model, determines the balance of false alarms and misses.",
  "Multiclass Classification": "Multiclass classification chooses one of three or more categories, usually by scoring every class and taking the highest.",
  "Logistic Regression": "Logistic regression predicts the probability of a class by passing a linear combination of features through a sigmoid, and remains a strong, interpretable baseline.",
  "K-Nearest Neighbors": "KNN classifies a point by the majority label of its nearest neighbours. It needs no training but is slow and scale-sensitive at prediction time.",
  "Naive Bayes": "Naive Bayes applies Bayes' theorem while assuming features are independent. The assumption is rarely true, yet it performs well on text.",
  "Support Vector Machines": "An SVM finds the boundary that separates classes with the widest margin, and kernels let it separate classes that are not linearly separable.",
  "Model Training": "Training is the loop of predicting, measuring error, and updating parameters until performance on held-out data stops improving.",
  Clustering: "Clustering groups similar records without labels. The groups are only useful once a human can describe what makes each one distinct.",
  "K-Means Intuition": "K-means alternates between assigning points to the nearest centre and moving each centre to the mean of its points, until the assignment stops changing.",
  "Choosing K": "Choosing k balances fit against interpretability, using the elbow method, silhouette scores, and whether the resulting groups mean anything.",
  "Elbow Method": "The elbow method plots within-cluster error against k and looks for the point where adding another cluster stops helping much.",
  "Hierarchical Clustering": "Hierarchical clustering builds a tree of nested groups, so you choose the number of clusters after seeing the structure rather than before.",
  DBSCAN: "DBSCAN groups points that are densely packed and labels sparse points as noise, so it finds irregular shapes and does not need k in advance.",
  "Association Rules": "Association rule mining finds items that co-occur, producing statements such as 'customers who bought A often bought B'.",
  "Why Model Evaluation?": "Evaluation answers whether the model would help in production. A single accuracy figure usually hides the failure mode that matters.",
  Accuracy: "Accuracy is the share of correct predictions. On imbalanced data it can look excellent while the model misses every case you care about.",
  Precision: "Precision asks: of everything flagged positive, how much really was. It is the metric to watch when false alarms are costly.",
  Recall: "Recall asks: of everything that truly was positive, how much did we find. It is the metric to watch when a miss is costly.",
  "F1 Score": "The F1 score is the harmonic mean of precision and recall, useful as one number when both errors matter.",
  "ROC Curve": "The ROC curve plots the true-positive rate against the false-positive rate across every threshold, showing the trade-off you can choose from.",
  AUC: "AUC is the area under the ROC curve, summarising how well the model ranks a random positive above a random negative.",
  MAE: "Mean absolute error is the average size of the error in the original units, and treats every error proportionally.",
  MSE: "Mean squared error averages the squared errors, which penalises large mistakes far more heavily than small ones.",
  RMSE: "Root mean squared error is the square root of MSE, returning the penalty-weighted error to the unit of the target.",
  "R²": "R² reports the share of variance in the target that the model explains. A negative value means the model is worse than predicting the mean.",
  "R² Score": "R² compares the model's remaining error with the variance of the target. One is perfect, zero is no better than the mean.",
  Hyperparameters: "Hyperparameters are settings chosen before training, such as tree depth or learning rate, as opposed to parameters learned from the data.",
  "Grid Search": "Grid search trains a model for every combination in a defined grid and keeps the best on validation. It is thorough but expensive.",
  "Random Search": "Random search samples combinations at random and usually finds a good configuration faster than a grid when only a few settings matter.",
  "L1 Regularization": "L1 (lasso) adds the sum of absolute weights to the loss, which drives weak coefficients to exactly zero and performs feature selection.",
  "L2 Regularization": "L2 (ridge) adds the sum of squared weights to the loss, shrinking all coefficients smoothly without eliminating any.",
  "Gradient Boosting": "Gradient boosting trains models in sequence, each one fitting the errors the previous ensemble still makes.",
  "XGBoost Introduction": "XGBoost is an optimised gradient boosting implementation with regularisation and efficient training, and remains a strong default for tabular data.",
  "Model Comparison": "Compare models on the same split with the same metric, and prefer the simplest one whose performance is not meaningfully worse.",
  Agent: "In reinforcement learning the agent is the decision maker that observes a state, chooses an action, and learns from the reward it receives.",
  Environment: "The environment is everything outside the agent. It receives the agent's action and returns the next state and a reward.",
  State: "A state is the information the agent has about the situation at one moment, and it must be enough to choose a sensible action.",
  Action: "An action is one of the choices available to the agent, and the set of allowed actions defines what it can possibly do.",
  Reward: "A reward is the numeric feedback after an action. Designing it badly is the fastest way to get behaviour you did not intend.",
  Policy: "A policy maps states to actions. Learning a good policy is the whole objective of reinforcement learning.",
  "Q-Learning": "Q-learning learns the expected long-term value of taking an action in a state, then acts by choosing the highest-value action.",
  "Exploration vs Exploitation": "Exploitation takes the best known action; exploration tries something else to learn more. Doing only one of the two is what fails.",
  "ML vs Deep Learning": "Classical ML works well on structured tabular data with limited examples; deep learning wins on images, audio, and text where data is plentiful.",
  "When to Use Deep Learning": "Reach for deep learning when the data is unstructured, the volume is large, and the pattern is too complex to express as features.",
  "Model Saving": "Saving a model preserves the fitted parameters and the preprocessing steps together, so the same input produces the same output later.",
  "Pickle / Joblib": "pickle and joblib serialise Python objects to disk. Never load a pickle from an untrusted source, because loading can execute code.",
  "Deploying an ML Model": "Deployment wraps the model in a service, applies the same preprocessing as training, validates inputs, and logs predictions for later review.",
  "Monitoring Models": "Model monitoring tracks input distributions, prediction distributions, and realised outcomes, so decay is caught early.",

  // ---------------------------------------------------------------- agents
  "AI vs Generative AI vs AI Agents": "AI is the broad field, generative AI creates new content from learned patterns, and an AI agent uses a model to decide and act toward a goal.",
  "LLM vs AI Agent": "An LLM produces a response. An agent wraps a model in a loop with tools, memory, and stopping rules so it can pursue a goal across several steps.",
  "Why AI Agents Matter": "Agents matter when a task needs several steps, live information, and real actions — work that a single prompt and response cannot complete.",
  "Real-World AI Agent Applications": "Agents are used for research assistants, customer support triage, code changes, data pipeline repair, and operational runbooks with human approval.",
  Prompts: "A prompt is the instruction and context given to a model. Being specific about the role, the task, the constraints, and the output shape does most of the work.",
  "System Prompt": "The system prompt sets persistent behaviour, role, and boundaries before the conversation starts, and should never contain secrets.",
  "User Prompt": "The user prompt carries the actual request and the context needed for this turn.",
  "Assistant Response": "The assistant response is the model's output for the turn, and becomes part of the context for the turns that follow.",
  "Model Parameters": "Parameters such as temperature, top-p, and maximum tokens shape how the model samples its output and how long that output can be.",
  "Structured Output": "Structured output constrains a response to a schema, so downstream code can parse it reliably instead of guessing at free text.",
  "Agent Brain": "The brain is the model that interprets the goal, decides the next step, and interprets each observation.",
  "Agent Goal": "The goal states what success looks like and when to stop. A vague goal produces an agent that loops without finishing.",
  "Agent Memory": "Memory is what the agent carries forward: short-term working state within a task, and long-term knowledge retained across tasks.",
  "Agent Tools": "Tools are the functions an agent may call to read or change the world. Each needs a schema, permissions, and predictable errors.",
  "Agent Planning": "Planning breaks a goal into ordered steps before acting, which reduces wasted tool calls and makes progress reviewable.",
  "Agent Reasoning": "Reasoning is the step where the model decides what to do next given the goal and everything observed so far.",
  "Agent Actions": "An action is one concrete tool call. Trusted application code, not the model, decides whether it is allowed to run.",
  "Agent Observation": "An observation is the real result returned by a tool, and it is what keeps the agent grounded in fact rather than assumption.",
  "What are Agent Tools?": "A tool is a described function the model can request. The description, the argument schema, and the returned errors are what make it usable.",
  "Why Agents Need Tools": "A model alone can only produce text. Tools let it read live data, perform calculations reliably, and change real systems.",
  "Tool Selection": "Tool selection is the model choosing which capability fits the current step. Fewer, clearly distinct tools produce better choices than many overlapping ones.",
  "Tool Parameters": "Parameters are the validated arguments a tool receives. A strict schema turns an ambiguous request into a safe call.",
  "Tool Results": "The result is the observation returned to the model. Keeping it small and structured avoids filling the context window with noise.",
  "Tool Errors": "Tool errors should be returned as clear, actionable messages so the agent can correct course instead of retrying the same failure.",
  "Why Agents Need Knowledge": "A model only knows what it was trained on plus what is in the prompt. Retrieval supplies the current, private, or specific facts it lacks.",
  Documents: "Documents are the source material for retrieval. Their quality, freshness, and permissions determine the quality of every grounded answer.",
  Context: "Context is everything placed in the model's window for this turn. It is a limited budget, so relevance matters more than volume.",
  "Traditional RAG vs Agentic RAG": "Traditional RAG retrieves once and answers. Agentic RAG lets the agent judge whether the retrieved material is sufficient and search again if it is not.",
  "Why MCP?": "MCP replaces bespoke integrations with one standard interface, so a tool built once can be used by any compatible AI application.",
  "MCP Client": "The MCP client lives inside the AI application and maintains the connection to one MCP server.",
  "MCP Server": "An MCP server exposes tools, resources, and prompts from a system so any MCP client can use them through the same protocol.",
  "MCP Tools": "MCP tools are executable functions the model can invoke, each with a described schema and its own permissions.",
  "MCP Resources": "MCP resources expose contextual data for the model to read, rather than actions for it to perform.",
  "MCP Prompts": "MCP prompts are reusable, parameterised templates a server offers so clients can invoke a known-good instruction.",
  "Single Agent vs Multi-Agent": "One agent is simpler to debug and usually enough. Multiple agents help when subtasks need genuinely different tools, context, or permissions.",
  "Agent Roles": "Assigning each agent a narrow role with its own tools and instructions keeps behaviour predictable and failures easy to trace.",
  "Supervisor Agent": "A supervisor decomposes the goal, delegates to workers, reviews their output, and decides when the task is complete.",
  "Worker Agent": "A worker agent performs one focused subtask with a small tool set and returns a structured result.",
  "Planner Agent": "A planner turns a goal into an ordered, reviewable set of steps before any action is taken.",
  "Research Agent": "A research agent gathers information from several sources, checks it for agreement, and reports findings with citations.",
  "Communication Between Agents": "Agents coordinate through structured messages or shared state. Free-form chat between agents is hard to debug and easy to derail.",
  Guardrails: "Guardrails are the enforced limits around an agent: allowed tools, validated arguments, filtered output, step and cost budgets, and human approval for risky actions.",
  "Agent Evaluation": "Evaluation scores an agent on realistic tasks with a fixed rubric, tracking task success, tool-call correctness, cost, and latency over time.",
  "Cost Optimization": "Cost is controlled by trimming context, caching repeated work, choosing a proportionate model, and capping the number of steps.",
  "Production Architecture": "A production agent separates the model, the tool layer, the permission checks, the state store, and the observability layer, so each can be tested and replaced.",
  "Agent State": "State is the structured record of what has happened so far, which is what allows an agent run to be inspected, resumed, or replayed.",
  "Graph-Based Agent Workflows": "A graph makes each step and transition explicit, so an agent's control flow becomes reviewable rather than emergent.",
  "Why Agent Frameworks?": "A framework supplies the loop, tool calling, state, and tracing so you write the task logic instead of the plumbing.",
  "Framework Comparison": "Frameworks differ in how much control they take: some give a minimal loop, others a full graph runtime with persistence and tracing.",
  "When to Use Each Framework": "Choose the smallest thing that fits: a plain loop for one tool, a framework when you need state, branching, retries, and tracing.",

  // ---------------------------------------------------------------- fullstack
  Browser: "The browser requests resources, parses HTML into a document tree, applies CSS, runs JavaScript, and paints the result to the screen.",
  URLs: "A URL names a resource: the scheme, the host, the path, and the optional query and fragment each control a different part of the request.",
  Domains: "A domain is a human-readable name that DNS translates into the IP address of a server.",
  Hosting: "Hosting is the service that runs your application and serves it to users, handling the machine, the network, and often the scaling.",
  "Full Stack Developer": "A full-stack developer works across the interface, the server, and the data layer, and understands how a change in one affects the others.",
  "HTML Document Structure": "An HTML document declares its type, then a head for metadata and a body for the visible content, in a nested tree of elements.",
  Elements: "An element is a tag pair with its content. Choosing the element that matches the meaning is what gives a page structure.",
  Attributes: "Attributes configure an element — its identity, its behaviour, its accessibility name — as name–value pairs on the opening tag.",
  "Semantic HTML": "Semantic HTML uses elements that describe meaning rather than appearance, which improves accessibility, SEO, and maintainability at once.",
  Accessibility: "Accessibility means the interface works for people using keyboards, screen readers, magnification, or reduced motion. It is a requirement, not a feature.",
  Selectors: "A CSS selector chooses which elements a rule applies to. Specificity decides which rule wins when several match.",
  Display: "The display property decides how an element generates boxes and how its children are laid out.",
  Position: "Positioning takes an element out of, or offsets it within, the normal flow. Prefer layout with flexbox or grid before reaching for it.",
  Animations: "CSS animations move properties over time. Animating transform and opacity keeps them smooth, and reduced-motion preferences must be honoured.",
  "Media Queries": "A media query applies rules only when a condition holds, such as a minimum viewport width, which is how one layout serves many screens.",
  Arrays: "An array is an ordered list of values with methods for adding, removing, searching, and transforming its contents.",
  Objects: "An object groups related values under named keys, and is the usual shape for a record passed between parts of an application.",
  Events: "An event is something that happened — a click, a submit, a key press — that code can listen for and respond to.",
  "Async JavaScript": "Asynchronous code starts work that finishes later without blocking the page, which is why network requests do not freeze the interface.",
  Modules: "Modules split code into files with explicit imports and exports, which keeps scope contained and dependencies visible.",
  "Local Storage": "localStorage keeps small string values in the browser between visits. It is readable by any script on the origin, so never store secrets in it.",
  "Why React?": "React is worth using when an interface has state that changes over time: it lets you describe what the UI should look like for a given state instead of manually patching the DOM.",
  JSX: "JSX is syntax that looks like markup and compiles to function calls, letting components describe their output in one readable expression.",
  Props: "Props are the read-only inputs passed from a parent to a child component, which is how data flows down the tree.",
  "Conditional Rendering": "Conditional rendering chooses what to display from the current state, and should include the empty, loading, and error cases as well as the happy path.",
  Forms: "A form collects input. Validate on the client for a fast response and on the server for safety, because only the server can be trusted.",
  useRef: "useRef holds a mutable value that survives re-renders without causing one, and is the usual way to reach a DOM node directly.",
  "Custom Hooks": "A custom hook extracts stateful logic into a reusable function, so several components can share behaviour without sharing markup.",
  "React Router": "A router maps URLs to components, so an application has real, shareable addresses and working browser navigation.",
  "Context API": "Context passes a value to a whole subtree without threading it through every prop, and suits genuinely global concerns such as theme or session.",
  useReducer: "useReducer centralises state transitions in one function, which is easier to reason about than several related useState calls.",
  "Redux Toolkit": "Redux Toolkit provides a predictable global store with reducers, actions, and devtools, and is worth its overhead when state is shared widely.",
  "API Integration": "Integrating an API means handling the request, the loading state, the success shape, and every failure mode the user could encounter.",
  "Loading States": "A loading state tells the user work is in progress. Without one, a slow response is indistinguishable from a broken page.",
  "Loading & Error States": "Every remote call has four outcomes to render: loading, empty, error, and success. Designing all four is what makes an interface feel reliable.",
  "Node.js": "Node.js runs JavaScript outside the browser on an event loop, which suits I/O-heavy servers and tooling.",
  "Node Runtime": "The Node runtime provides the event loop, the module system, and the APIs for files, networking, and processes.",
  npm: "npm installs and version-locks the packages a project depends on, and runs the scripts that build, test, and start it.",
  Server: "A server listens for requests, routes each to a handler, applies trusted rules, and returns a response.",
  Routes: "A route maps a method and path to the code that handles it, which is the entry point of every API request.",
  Controllers: "A controller translates an HTTP request into a call to business logic and turns the result into a response. It should stay thin.",
  Services: "A service holds the business rules, independent of HTTP, so the same logic can be reused and unit-tested.",
  "Request Body": "The request body carries the data being sent. Validate it against a schema before any of it reaches your logic.",
  "Query Parameters": "Query parameters carry optional inputs such as filters, sorting, and pagination in the URL, and must be validated like any other input.",
  CRUD: "CRUD names the four basic data operations — create, read, update, delete — that most applications are built from.",
  "CRUD in MongoDB": "MongoDB's CRUD operations act on documents in a collection: insert, find, update, and delete, each with filters and options.",
  Collections: "A collection groups related documents. Unlike a SQL table it does not enforce one shape, so validation belongs in the application or a schema.",
  "Database Security": "Database security means least-privilege accounts, encrypted connections, parameterised queries, restricted network access, and tested backups.",
  Registration: "Registration creates an account: validate the input, check uniqueness, hash the password, and confirm ownership of the contact address.",
  Sessions: "A session stores authentication state on the server and gives the client an opaque identifier, so the server can revoke access immediately.",
  Cookies: "A cookie is a small value the browser stores and returns automatically. Auth cookies should be HttpOnly, Secure, and SameSite.",
  "Access Tokens": "An access token proves an identity for a short period. Keeping its lifetime short limits the damage if it leaks.",
  "Environment Variables": "Environment variables hold configuration and secrets outside the code, so the same build runs safely in different environments.",
  Repository: "A repository is a project folder whose full history Git tracks, including every commit, branch, and tag.",
  "git init": "git init creates a new repository in the current folder, after which Git begins tracking changes you stage and commit.",
  "git clone": "git clone copies an existing repository, including its history, and sets up the link back to the original.",
  "git add": "git add stages the changes you want in the next commit, which lets you commit a coherent subset of your work.",
  "git commit": "git commit records the staged changes with a message. Small, focused commits with honest messages are what make history useful.",
  "git push": "git push uploads local commits to the remote so others can see and build on them.",
  "git pull": "git pull fetches remote commits and integrates them into your branch, which is where conflicts usually surface.",
  Merge: "Merging combines the history of two branches. When both changed the same lines, Git asks you to resolve the conflict.",
  "GitHub Issues": "An issue tracks one piece of work — a bug, a task, or a question — with the context needed for someone else to pick it up.",
  README: "A README explains what the project is, how to run it, and how to contribute. It is the first thing a reviewer or employer reads.",
  "Why Testing?": "Tests exist to catch regressions cheaply and to let a team change code with confidence. Without them every change is a gamble.",
  "Unit Testing": "A unit test checks one small piece of logic in isolation. It is fast, precise about what broke, and cheap to run on every commit.",
  "Integration Testing": "An integration test checks that parts work together — code with a database, or one service with another — where unit tests cannot see.",
  "API Testing": "API testing verifies status codes, response shapes, validation, authorisation, and error handling directly against the interface contract.",
  "Frontend Testing": "Frontend testing checks that components render the right output for a given state and that user interactions produce the expected result.",
  "Backend Testing": "Backend testing verifies business rules, data access, permissions, and error handling on the server, where the trusted decisions are made.",
  "Edge Cases": "Edge cases are the boundaries and unusual inputs — empty, maximum, duplicate, malformed — where defects concentrate.",
  "Build Process": "The build turns source code into the artifact that actually runs: compiled, bundled, minified, and configured for its target environment.",
  Images: "A container image is an immutable, layered package containing the application and everything it needs to run.",
  Containers: "A container is a running instance of an image, isolated from the host but sharing its kernel, which makes it fast to start and cheap to replace.",
  "Cloud Deployment": "Cloud deployment runs the application on managed infrastructure, trading some control for scaling, availability, and less operational work.",
  "Reverse Proxy": "A reverse proxy sits in front of your application to terminate TLS, route requests, balance load, and serve cached content.",
  "Production Logs": "Production logs are the record of what actually happened. Structured logs with request identifiers are what make an incident traceable.",
  "File Upload": "File upload needs a size limit, a type allowlist, a scan or validation step, and storage outside the web root.",
  "Search and Filtering": "Search and filtering narrow a large collection. Doing the work in the database with indexes keeps it fast as the data grows.",
  "Admin Panel": "An admin panel gives privileged users controlled access to manage data, and needs stricter authorisation and audit logging than the rest of the app.",

  // ---------------------------------------------------------------- mern
  Destructuring: "Destructuring pulls values out of an object or array into named variables in one statement, which makes function signatures and imports much clearer.",
  "Spread Operator": "The spread operator expands an array or object into a new one, which is how state is updated immutably.",
  "Array Methods": "map, filter, reduce, and find transform arrays without mutating them, which keeps data flow easy to follow.",
  "ES6+": "Modern JavaScript adds let and const, arrow functions, template literals, destructuring, modules, classes, and async/await.",
  Vite: "Vite serves source files directly during development for near-instant reloads, and produces an optimised bundle for production.",
  "React Introduction": "React builds interfaces from components whose output is derived from props and state, so the UI stays a function of the data.",
  "React State": "State is the data a component owns and can change. Where you place it determines which parts of the tree re-render.",
  "API Calls": "An API call is an asynchronous request. Handle the loading, success, empty, and error paths, and cancel it if the component unmounts.",
  Axios: "Axios is an HTTP client with interceptors, automatic JSON handling, and consistent errors, which suits shared request configuration.",
  Routing: "Routing maps a request path to the handler that answers it, on the server or in the browser.",
  Request: "The request object carries the method, path, headers, query, and body — every input the handler must validate before use.",
  Response: "The response carries the status code, headers, and body. Choosing an honest status code is part of the API contract.",
  Validation: "Validation rejects malformed input at the boundary with a clear message, before it can reach the business logic or the database.",
  Search: "Search finds records matching a term. Doing it in the database with an appropriate index keeps it usable as data grows.",
  "API Documentation": "Documentation states every endpoint's method, path, inputs, outputs, errors, and auth requirements, so consumers do not have to guess.",
  Database: "A database keeps application data durable, consistent, and queryable, and enforces the rules that keep it valid.",
  Collection: "A collection is MongoDB's container for related documents, equivalent in role to a table but without an enforced schema.",
  Document: "A document is one record in MongoDB, stored as BSON with flexible, possibly nested fields.",
  "MongoDB Atlas": "Atlas is MongoDB's managed cloud service, handling provisioning, backups, scaling, and network access controls.",
  "MongoDB Compass": "Compass is a graphical client for browsing collections, building queries, and inspecting index and query performance.",
  Queries: "A query describes which documents to return using filters, projections, sorting, and limits.",
  Schemas: "A Mongoose schema declares the expected fields, types, defaults, and validation rules for documents in a collection.",
  Models: "A Mongoose model is compiled from a schema and provides the methods used to create, query, update, and delete documents.",
  "User Registration": "Registration validates the input, enforces a unique identifier, hashes the password with a slow algorithm, and never echoes the credentials back.",
  "Admin Authentication": "Admin authentication applies stricter controls — separate roles, re-authentication for sensitive actions, and full audit logging.",
  Security: "Security in a web application means validating input, authenticating and authorising every request, protecting secrets, and logging what happened.",
  "Connect React to Express": "The React client calls the Express API over HTTP with JSON, and both sides must agree on the URL, the shape, the auth header, and the error format.",
  "Authentication Flow": "The flow runs from login, to issuing a token or session, to attaching it on each request, to verifying it server-side, to refresh and logout.",
  "Backend Validation": "Client-side validation is a convenience; server-side validation is the real defence, because a client can always be bypassed.",
  "Database Operations": "Every data operation should be scoped to the authenticated user, validated, and wrapped in a transaction when several writes must succeed together.",
  "Production Build": "A production build strips development tooling, minifies and bundles assets, and injects the configuration for the target environment.",
  Performance: "Performance work starts with measurement: find the slow path, fix the largest cost, then measure again.",

  // ---------------------------------------------------------------- testing
  "Quality Control": "Quality control inspects the product to find defects. Quality assurance improves the process so fewer defects are created.",
  "QA vs QC vs Testing": "QA improves the process, QC inspects the product, and testing is the activity that produces the evidence QC relies on.",
  Verification: "Verification asks whether we built the product correctly, against its specification.",
  "Software Testing Principles": "Testing shows the presence of defects, exhaustive testing is impossible, defects cluster, testing should start early, and the same tests stop finding new problems over time.",
  "Testing Mindset": "A tester assumes the requirement may be wrong, looks for the conditions nobody considered, reproduces before reporting, and argues from evidence.",
  "Tester Responsibilities": "A tester analyses requirements, designs and runs checks, reports defects with reproducible evidence, verifies fixes, and reports risk honestly.",
  "QA Career Paths": "QA careers branch into manual and exploratory specialism, automation engineering, performance, security, and quality leadership.",
  Waterfall: "Waterfall completes each phase before the next begins. It suits stable, well-specified requirements and reacts poorly to change.",
  Agile: "Agile delivers in short iterations with continuous feedback, so testing happens throughout rather than at the end.",
  Scrum: "Scrum organises work into fixed sprints with defined roles and ceremonies, and treats testing as part of the definition of done.",
  Kanban: "Kanban visualises work in progress and limits it, so items finish rather than accumulate.",
  "V-Model": "The V-model pairs each development phase with the test level that verifies it, so test design starts alongside design rather than after coding.",
  "Requirement Analysis": "Requirement analysis identifies what is testable, what is ambiguous, and what risk each requirement carries, before any test is written.",
  "Test Planning": "A test plan states the scope, the approach, the environment, the entry and exit criteria, the risks, and who does what.",
  "Test Design": "Test design chooses the conditions worth checking, using techniques such as boundary values, equivalence classes, and decision tables.",
  "Test Execution": "Execution runs the designed checks in a controlled environment and records the actual result against the expected one with evidence.",
  "Defect Reporting": "A defect report gives a precise title, the environment, exact reproduction steps, expected versus actual behaviour, evidence, severity, and priority.",
  "Test Closure": "Closure summarises what was tested, what was found, what remains open, and what risk the team is accepting at release.",
  "Test Scenario": "A test scenario is a high-level statement of what to verify. One scenario usually expands into several concrete test cases.",
  Preconditions: "Preconditions state the system state required before the steps begin, without which a test is not reliably repeatable.",
  "Expected Result": "The expected result is the behaviour the requirement promises, written before execution so the outcome cannot be rationalised afterwards.",
  "Actual Result": "The actual result is what the system really did, recorded with enough evidence for someone else to confirm it.",
  "Functional Testing": "Functional testing verifies that a feature does what the requirement says, from the user's point of view.",
  "Smoke Testing": "A smoke test is a short check that the build is stable enough to test further. It fails fast rather than testing deeply.",
  "Sanity Testing": "A sanity check verifies that a specific fix or change works, without re-running the full suite.",
  "Regression Testing": "Regression testing re-runs existing checks to confirm that a change did not break behaviour that previously worked.",
  Retesting: "Retesting confirms that a specific reported defect is genuinely fixed, using the original reproduction steps.",
  "Exploratory Testing": "Exploratory testing designs, runs, and learns at the same time, which is how defects nobody scripted for are found.",
  "Usability Testing": "Usability testing observes whether real users can complete their task without confusion, and where they hesitate.",
  "Compatibility Testing": "Compatibility testing verifies the product across the browsers, devices, operating systems, and screen sizes the users actually have.",
  "Accessibility Testing": "Accessibility testing checks keyboard operation, screen-reader output, contrast, focus order, and labels against a standard such as WCAG.",
  UAT: "User acceptance testing lets the business confirm the product meets the real need before release. It validates fitness, not code correctness.",
  "Positive Testing": "Positive testing confirms the system works with valid input on the expected path.",
  "Negative Testing": "Negative testing supplies invalid, missing, or hostile input and confirms the system fails safely with a clear message.",
  "Decision Tables": "A decision table lists every combination of conditions and the expected outcome for each, which exposes rules nobody had considered.",
  "State Transition Testing": "State transition testing checks the allowed moves between states, and confirms that forbidden transitions are actually refused.",
  "Risk-Based Testing": "Risk-based testing spends effort where the likelihood and impact of failure are highest, rather than spreading it evenly.",
  "Test Coverage": "Coverage measures how much of the requirements, code, or data classes the tests exercise. High coverage of trivial checks proves little.",
  "Traceability Matrix": "A traceability matrix maps requirements to test cases and results, making coverage gaps visible.",
  "Test Case Review": "Reviewing test cases catches ambiguous steps, missing preconditions, and untestable expectations before execution wastes time.",
  "Test Case Optimization": "Optimisation removes duplicate and low-value checks and merges overlapping ones, so the suite stays fast enough to run often.",
  "Defect vs Error vs Failure": "A person makes an error, which introduces a defect in the product, which causes a failure when the defective code runs.",
  "Bug Lifecycle": "A defect moves from new, to assigned, to fixed, to retested, to closed — or is rejected, deferred, or reopened along the way.",
  Severity: "Severity describes the technical impact of a defect on the system, and is judged by the tester.",
  Priority: "Priority describes how urgently the business needs it fixed, and is judged by the product owner.",
  Blocker: "A blocker stops further testing or use entirely, so nothing else can proceed until it is resolved.",
  Critical: "A critical defect breaks a core function or causes data loss, with no acceptable workaround.",
  Major: "A major defect significantly impairs a feature, though a workaround may exist.",
  Minor: "A minor defect causes limited inconvenience and does not prevent the user from completing their task.",
  "Bug Report": "A useful bug report is reproducible by a stranger: precise title, environment, steps, expected versus actual, evidence, and impact.",
  "Reproduction Steps": "Reproduction steps are the exact, ordered actions from a known starting state that make the defect appear every time.",
  Screenshots: "A screenshot or recording shows what words cannot, and should capture the surrounding context, not only the error.",
  Logs: "Logs show what the system was doing when it failed, and attaching the relevant excerpt often saves a developer hours.",
  "Bug Triage": "Triage is the regular meeting where new defects are confirmed, prioritised, and assigned, so the backlog reflects real risk.",
  "Jira Introduction": "Jira tracks issues through a configurable workflow, linking defects to requirements, releases, and the evidence attached to them.",
  "REST API": "A REST API exposes resources at URLs and uses HTTP methods and status codes to express intent and outcome.",
  GET: "GET reads a resource and must not change anything, which is what makes it safe to retry and cache.",
  POST: "POST creates a resource or submits data for processing, and is not idempotent — sending it twice may create two records.",
  PUT: "PUT replaces a resource entirely with the supplied representation, and repeating it produces the same result.",
  PATCH: "PATCH applies a partial update to a resource, changing only the fields supplied.",
  DELETE: "DELETE removes a resource. It should be idempotent: deleting something already gone is still a success.",
  Headers: "Headers carry metadata about the request or response — content type, authentication, caching — and are as testable as the body.",
  "API Test Cases": "API test cases cover the happy path, validation failures, authentication and authorisation, boundary data, and error responses.",
  "API Automation Basics": "API automation asserts on status, body, headers, and timing, and runs in CI so contract breaks are caught on every commit.",
  "UI vs Database Validation": "The interface can display a value that was never stored, or hide one that was. Checking both is what catches that class of defect.",
  "API + Database Testing": "Combining API and database checks confirms that a request produced exactly the intended change and no unintended ones.",
  "Why Automation?": "Automation is worth it for checks that are repetitive, stable, and run often. It frees people for the exploratory work only people can do.",
  "Manual vs Automation": "Manual testing finds the unexpected; automation guards the known. A healthy suite uses both deliberately.",
  Installation: "A reproducible test setup pins the tool version, the browsers, and the configuration, so results do not depend on the machine.",
  "Browser Automation": "Browser automation drives a real browser through a script, performing the actions a user would and asserting on what appears.",
  Locators: "A locator identifies the element to act on. Role and label based locators survive redesigns; brittle CSS chains do not.",
  Assertions: "An assertion states what must be true. A test without a meaningful assertion passes even when the feature is broken.",
  Click: "A click test should wait for the element to be actionable, perform the click, and assert on the resulting state rather than on the click itself.",
  Fill: "Filling an input should target it by its label, enter realistic data, and verify the value the application actually received.",
  Navigation: "Navigation tests confirm the correct page loads, the URL is right, and the state survives forward, back, and reload.",
  "Test Hooks": "Hooks run setup and teardown around tests, keeping each one independent by restoring a known starting state.",
  "Page Objects": "The page object pattern puts locators and interactions in one place, so a UI change is fixed once instead of in every test.",
  "Test Reports": "A report shows what ran, what failed, and why, with traces and screenshots, so a failure can be diagnosed without re-running it.",
  "Parallel Testing": "Running tests in parallel cuts feedback time, and requires each test to be independent and to use isolated data.",
  "Cross-Browser Testing": "Cross-browser testing verifies behaviour on every engine the users have, because rendering and API support genuinely differ.",
  "CI Integration": "Running tests in CI on every push makes quality a shared, automatic gate rather than an individual habit.",
  "Load Testing": "Load testing measures behaviour under expected traffic, checking response time, throughput, and error rate at realistic volume.",
  "Stress Testing": "Stress testing pushes past the expected load to find where the system breaks and whether it fails gracefully.",
  "Spike Testing": "Spike testing applies a sudden surge to see whether the system absorbs it and recovers.",
  "Endurance Testing": "Endurance testing holds a sustained load for hours to reveal slow leaks and gradual degradation.",
  "Response Time": "Response time is how long a request takes end to end. Report percentiles, because the average hides the worst experiences.",
  Throughput: "Throughput is how many requests the system completes per unit of time at an acceptable response time.",
  "Apache JMeter": "JMeter scripts and runs load tests against APIs and web applications, reporting throughput, latency, and errors under controlled load.",
  "Basic Security Testing": "Basic security testing checks authentication, authorisation, input handling, secure transport, and whether errors leak internal detail.",
  "Authentication Testing": "Authentication testing verifies login, lockout, session expiry, password rules, and that protected pages refuse unauthenticated access.",
  "Authorization Testing": "Authorisation testing confirms that a user cannot reach another user's data by changing an identifier in the URL or request.",
  "Mobile Testing": "Mobile testing covers real devices, screen sizes, touch interaction, network variability, and interruptions such as calls and rotation.",
  "Git for Testers": "Testers use Git to version test code and data, work on branches, review changes, and keep automation alongside the application.",
  "Automated Test Pipelines": "A pipeline runs the suite automatically on every change and blocks the merge when a check fails.",
  "Release Quality Gates": "A quality gate is an agreed, measurable condition — tests passing, no open blockers, coverage of critical paths — that a release must meet.",
  "Generative AI for Test Cases": "A model can draft test cases and data quickly, but a tester must verify each against the real requirement before it is trusted.",
  "AI-Generated Test Data": "Generated data covers more variety fast, and must still be checked for realistic distributions, valid formats, and no real personal data.",
  "AI-Assisted Bug Analysis": "A model can summarise logs and suggest likely causes, which speeds triage. The confirmed root cause still needs evidence.",
  "AI Defect Hotspot Analysis": "Hotspot analysis uses historical defect and change data to point testing at the modules most likely to break.",
  "Responsible Use of AI in QA": "Never paste confidential data into an external tool, always verify generated output against the requirement, and keep a human accountable for the sign-off.",
  "End-to-End QA Workflow": "The full workflow runs from requirement analysis, through test design and execution, to defect management, regression, and a documented sign-off.",
  "QA Dashboard": "A QA dashboard shows execution progress, pass rate, open defects by severity, and coverage of critical paths, so release risk is visible.",
  "Final Sign-Off Report": "A sign-off report states what was tested, the results, the open defects, the risks being accepted, and the recommendation to release or not.",
};

