for (const [title, text] of Object.entries({ ...additionalDefinitions, ...subjectCourseDefinitions, ...softwareDefinitions })) {
  if (!topicDefinitions[title]) topicDefinitions[title] = text;
}

/**
 * Titles that mean different things in different courses. A "collection" is a
 * MongoDB container in a backend course and a saved group of requests in a QA
 * course, so the subject decides which definition a lesson receives.
 */
export const subjectDefinitions: Record<string, Record<string, string>> = {
  fullstack: {
    Documents: "A MongoDB document is a record stored as BSON, with a flexible set of fields that may nest other documents and arrays.",
  },
  mern: {
    Documents: "A MongoDB document is a record stored as BSON, with a flexible set of fields that may nest other documents and arrays.",
  },
  testing: {
    "Why Testing?": "Testing gives evidence about risk before users find it. It cannot prove a product is bug-free, but it can show that the important behaviours work.",
    Validation: "Validation asks whether we built the correct product, against the user's real need.",
    "Test Data": "Test data is the input a check needs, including the valid, boundary, invalid, and realistic-volume cases.",
    Collections: "A Postman collection groups related requests with shared variables and tests, so an API can be exercised repeatably.",
    "Data Validation": "Data validation confirms that what the interface reported is what the system actually stored, in the right type, format, and range.",
    "Backend Validation": "Backend validation checks that server rules reject invalid data even when the interface would have allowed it.",
  },
};

/** Definition for a lesson title, preferring a subject-specific wording. */
export function definitionFor(title: string, subject: string) {
  return subjectDefinitions[subject]?.[title] ?? topicDefinitions[title];
}
